settings.liquid:
{% if product %}
  {% assign sub = product.metafields.descriptors.subtitle 
    | default: "Smooths tummy, snatches waist & stays invisible." %}

  <div class="cf-mech-block">
    <div class="cf-mech-head">CURVEFLEX™ SCULPT LAYER</div>
    <div class="cf-mech-sub">{{ sub }}</div>
  </div>

  <style>
    .cf-mech-block{ margin:6px 0 10px; }
    .cf-mech-head{
      font-size:13px;
      font-weight:600;
      letter-spacing:.05em;
      text-transform:uppercase;
      color:#6c6d70;          /* muted grey for premium tone */
      margin-bottom:2px;
    }
    .cf-mech-sub{
      font-size:14px;
      line-height:1.45;
      color:#111;             /* keep body text in black */
      font-weight:400;
    }
    @media (min-width:768px){
      .cf-mech-head{ font-size:14px; }
      .cf-mech-sub{ font-size:15px; }
    }
  </style>
{% endif %}

{%- comment -%}
CURVJEANS — Shapewear “Compression Level” row
• No <details>; exact Impact-like row with chevron button
• Body uses [hidden] so it occupies ZERO space when closed
• Default open, but closable; set data-open="false" to start closed
• Support (optional): product.metafields.shopify.support.value (metaobject)
• Fit tip (optional): product.metafields.shopify.fit.value
{%- endcomment -%}

{%- assign _lc = localization.language.iso_code | default: shop.locale | default: 'EN' | upcase -%}
{%- if _lc == 'NL' -%}
  {%- assign t_head='Compressieniveau' -%}
  {%- assign t_light='Licht' -%}{%- assign t_medium='Medium' -%}{%- assign t_strong='Sterk' -%}
  {%- assign d_light='Licht corrigerend — ademend en flexibel.' -%}
  {%- assign d_medium='Dagelijks gladstrijken met comfortabele steun.' -%}
  {%- assign d_strong='Sterke, gerichte compressie voor shapen & sculpten.' -%}
  {%- assign t_fit_up='Twijfel je? Neem 1 maatje groter.' -%}
{%- elsif _lc == 'DE' -%}
  {%- assign t_head='Kompressionsstärke' -%}
  {%- assign t_light='Leicht' -%}{%- assign t_medium='Mittel' -%}{%- assign t_strong='Stark' -%}
  {%- assign d_light='Leichte Formung — atmungsaktiv und flexibel.' -%}
  {%- assign d_medium='Tägliches Glätten mit bequemem Halt.' -%}
  {%- assign d_strong='Starke, gezielte Kompression für Form & Sculpting.' -%}
  {%- assign t_fit_up='Wenn zwischen Größen, eine größer nehmen.' -%}
{%- else -%}
  {%- assign t_head='Compression Level' -%}
  {%- assign t_light='Light' -%}{%- assign t_medium='Medium' -%}{%- assign t_strong='Strong' -%}
  {%- assign d_light='Light smoothing — breathable, flexible.' -%}
  {%- assign d_medium='Everyday smoothing with comfy hold.' -%}
  {%- assign d_strong='Strong, targeted compression for shaping & sculpting.' -%}
  {%- assign t_fit_up='Size up if in between.' -%}
{%- endif -%}

{%- assign sup_val = product.metafields.shopify.support.value -%}
{%- assign sup_json = sup_val | json -%}
{%- assign sup = sup_val -%}{% if sup_val and sup_json contains '[' %}{%- assign sup = sup_val | first -%}{% endif %}
{%- assign s_handle = sup.handle | default: '' | downcase -%}
{%- assign s_label  = sup.label  | default: sup.title | default: sup.name | default: sup | downcase -%}

{%- assign bars = 5 -%}{%- assign line = t_strong -%}{%- assign desc = d_strong -%}
{%- if s_handle contains 'light' or s_label contains 'light' -%}
  {%- assign bars = 2 -%}{%- assign line = t_light -%}{%- assign desc = d_light -%}
{%- elsif s_handle contains 'medium' or s_label contains 'medium' -%}
  {%- assign bars = 3 -%}{%- assign line = t_medium -%}{%- assign desc = d_medium -%}
{%- endif -%}

{%- assign fit_val = product.metafields.shopify.fit.value -%}
{%- assign fit_json = fit_val | json -%}
{%- assign fit_entry = fit_val -%}{% if fit_val and fit_json contains '[' %}{%- assign fit_entry = fit_val | first -%}{% endif %}
{%- assign f_handle = fit_entry.handle | default: '' | downcase -%}
{%- assign f_label  = fit_entry.label  | default: fit_entry.title | default: fit_entry.name | default: fit_entry | downcase -%}
{%- assign fit_tip = '' -%}
{%- if f_handle contains 'slim' or f_handle contains 'snug' or f_handle contains 'straight' or f_label contains 'slim' or f_label contains 'snug' or f_label contains 'straight' -%}
  {%- assign fit_tip = t_fit_up -%}
{%- endif -%}

<style>
  :root{
    --curv-border: rgba(17,17,17,.08);
    --row-pad-y: 14px;     /* adjust 12–16 to match Impact */
    --chev-size: 24px;
    --chev-icon: 10px;
  }
  .cj-shp-acc{ color:#000; margin:16px 0 0; border-top:1px solid var(--curv-border); }
  .cj-shp-acc__head{
    display:flex; align-items:center; justify-content:space-between;
    padding:var(--row-pad-y) 0; line-height:1;
  }
  .cj-shp-acc__title{ font-weight:700; color:#000; }

  /* Theme chevron */
  .cj-shp-acc__chevbtn{
    width:var(--chev-size); height:var(--chev-size);
    border-radius:999px; background:#EDEDED;
    display:inline-flex; align-items:center; justify-content:center;
    flex:0 0 auto;
  }
  .cj-shp-acc__chev{
    width:var(--chev-icon); height:var(--chev-icon);
    stroke:#000; stroke-width:2.6; stroke-linecap:round; stroke-linejoin:round; fill:none;
    transition:transform .2s ease;
  }
  .cj-shp-acc.is-open .cj-shp-acc__chev{ transform:rotate(180deg); } /* open state */

  /* Panel — hidden removes space entirely */
  .cj-shp-acc__panel[hidden]{ display:none !important; }
  .cj-shp-acc__panel{ padding:0 0 12px; }

  /* Bars */
  .cj-bars{ display:inline-flex; align-items:flex-end; gap:3px; height:14px; margin-right:.5rem; }
  .cj-bar{ width:3px; background:#e5e7eb; border-radius:2px; }
  .cj-bar:nth-child(1){ height:5px } .cj-bar:nth-child(2){ height:7px }
  .cj-bar:nth-child(3){ height:9px } .cj-bar:nth-child(4){ height:11px }
  .cj-bar:nth-child(5){ height:13px }
  .cj-bar.is-on{ background:#000; }

  .cj-line{ display:flex; align-items:center; gap:.5rem; margin:0 0 6px; }
  .cj-level{ font-weight:600; color:#000; }
  .cj-desc, .cj-tip{ color:#000; margin:.25rem 0 0; line-height:1.45; }

  /* seam into next native row */
  .cj-shp-acc + details{ margin-top:0 !important; }
</style>

<section class="cj-shp-acc{% if true %} is-open{% endif %}" id="cj-shp-acc" data-open="true" role="group" aria-label="{{ t_head }}">
  <div class="cj-shp-acc__head" role="button" tabindex="0" aria-controls="cj-shp-panel" aria-expanded="true">
    <span class="cj-shp-acc__title">{{ t_head }}</span>
    <span class="cj-shp-acc__chevbtn" aria-hidden="true">
      <svg class="cj-shp-acc__chev" viewBox="0 0 20 20"><path d="M5 8l5 5 5-5"/></svg>
    </span>
  </div>

  <div class="cj-shp-acc__panel" id="cj-shp-panel">
    <div class="cj-line">
      <span class="cj-bars" role="img" aria-label="{{ line }}">
        {%- for i in (1..5) -%}<span class="cj-bar{% if i <= bars %} is-on{% endif %}"></span>{%- endfor -%}
      </span>
      <span class="cj-level">{{ line }}</span>
    </div>
    <p class="cj-desc">{{ desc }}</p>
    {%- if fit_tip != '' -%}<p class="cj-tip">{{ fit_tip }}</p>{%- endif -%}
  </div>
</section>

<script>
(function(){
  var root = document.getElementById('cj-shp-acc');
  if(!root) return;

  var head = root.querySelector('.cj-shp-acc__head');
  var panel = root.querySelector('.cj-shp-acc__panel');
  var startOpen = (root.getAttribute('data-open') || 'true') === 'true';

  function setOpen(open){
    root.classList.toggle('is-open', open);
    head.setAttribute('aria-expanded', open ? 'true' : 'false');
    if(open){ panel.removeAttribute('hidden'); } else { panel.setAttribute('hidden',''); }
  }
  setOpen(startOpen);

  head.addEventListener('click', function(){ setOpen(!(root.classList.contains('is-open'))); });
  head.addEventListener('keydown', function(e){
    if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); head.click(); }
  });
})();
</script>

<style>
  /* kill the wrapper’s top gap */
  #cj-shp-acc + .product-info__block-group.accordion-group[data-group-type="accordion-group"]{
    margin-top:0 !important;
    padding-top:0 !important;
    border-top:0 !important; /* some themes add a top border -> looks like space */
  }
</style>

<style>
  /* 1) Remove the leftover top margin on our custom row */
  #cj-shp-acc{ margin-top:0 !important; }

  /* optional: keep bottom feel identical to theme */
  #cj-shp-acc .cj-shp-acc__panel{ padding-bottom:0; }
</style>

<script>
/* 2) Auto-sync our row padding to the theme’s accordion row,
      so the title sits perfectly centered between the hairlines */
(function(){
  var root = document.getElementById('cj-shp-acc');
  if(!root) return;

  // Find a native accordion toggle to copy spacing from
  var ref = document.querySelector(
    '.product-info__accordion .accordion__toggle, ' +
    'details.product-info__accordion .accordion__toggle'
  );

  if (ref) {
    var cs = getComputedStyle(ref);
    var py = parseFloat(cs.paddingTop) || 16;  // Impact is usually ~16–18px
    root.style.setProperty('--row-pad-y', py + 'px');
  }

  // If the next wrapper still declares a top margin, zero it inline (just in case)
  var next = root.nextElementSibling;
  if (next && next.matches('.product-info__block-group.accordion-group[data-group-type="accordion-group"]')) {
    next.style.setProperty('margin-top','0','important');
    next.style.setProperty('margin-block-start','0','important');
  }
})();
</script>
